"use strict";
const test = require("node:test"), assert = require("node:assert/strict");
const fs = require("node:fs"), os = require("node:os"), path = require("node:path"), crypto = require("node:crypto");
const { pack, assemble } = require("../scripts/package-agent-release.cjs");
test("repository artifacts reassemble byte-for-byte and reject corrupt parts without replacing an installer", t => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "qa-agent-bundle-"));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const source = path.join(dir, "source"), parts = path.join(dir, "parts"), output = path.join(dir, "output");
  fs.mkdirSync(source);
  const name = "qa-report-agent-0.4.0-mac-arm64.dmg", bytes = Buffer.from([0, 12, 255, 4]);
  fs.writeFileSync(path.join(source, name), bytes);
  fs.writeFileSync(path.join(source, "installers.json"), JSON.stringify({ version: "0.4.0", files: [{ name, size: bytes.length, sha256: crypto.createHash("sha256").update(bytes).digest("hex") }] }));
  fs.writeFileSync(path.join(source, "latest.json"), '{"signature":"fixture"}');
  fs.writeFileSync(path.join(source, "qr-report-agent-code-0.4.0.asar"), "code");
  fs.writeFileSync(path.join(source, "private.pem"), "must not enter the bundle");
  pack(source, parts); assemble(parts, output);
  assert.deepEqual(fs.readFileSync(path.join(output, name)), bytes);
  assert.equal(fs.readdirSync(parts).some(name => name.includes("private")), false);
  fs.writeFileSync(path.join(parts, `${name}.part-001`), Buffer.from([0, 12, 255, 5]));
  assert.throws(() => assemble(parts, output), /checksum mismatch/);
  assert.deepEqual(fs.readFileSync(path.join(output, name)), bytes);
  assert.equal(fs.readdirSync(output).some(name => name.endsWith(".part")), false);
  const manifestPath = path.join(parts, "bundle.json"), manifest = JSON.parse(fs.readFileSync(manifestPath));
  manifest.files[0].parts[0].name = "../private.pem";
  fs.writeFileSync(manifestPath, JSON.stringify(manifest));
  assert.throws(() => assemble(parts, output), /Invalid release part/);
});
